#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define LOG 17

static int N, B, C;

typedef struct { int a, b, w; } Edge;
static Edge edges[MAXN];

/* DSU */
static int dsu[MAXN];
static int find(int x){ while(dsu[x]!=x){ dsu[x]=dsu[dsu[x]]; x=dsu[x]; } return x; }

/* MST adjacency */
static int head[MAXN], nxt[2*MAXN], to[2*MAXN], wt[2*MAXN], ecnt;

static void addEdge(int u,int v,int w){
    to[ecnt]=v; wt[ecnt]=w; nxt[ecnt]=head[u]; head[u]=ecnt++;
}

static int dep[MAXN], par[LOG][MAXN], minw[LOG][MAXN];
static int order[MAXN], ocnt;

static int cmpEdge(const void *p, const void *q){
    return ((const Edge*)q)->w - ((const Edge*)p)->w;
}

int main(void){
    if(scanf("%d %d",&N,&B)!=2) return 0;
    for(int i=0;i<B;i++){
        int a,b,w; scanf("%d %d %d",&a,&b,&w);
        edges[i].a=a; edges[i].b=b; edges[i].w=w;
    }
    qsort(edges,B,sizeof(Edge),cmpEdge);
    for(int i=1;i<=N;i++) dsu[i]=i, head[i]=-1;
    ecnt=0;
    int taken=0;
    for(int i=0;i<B && taken<N-1;i++){
        int ra=find(edges[i].a), rb=find(edges[i].b);
        if(ra!=rb){
            dsu[ra]=rb;
            addEdge(edges[i].a,edges[i].b,edges[i].w);
            addEdge(edges[i].b,edges[i].a,edges[i].w);
            taken++;
        }
    }
    /* BFS from node 1 */
    static int qq[MAXN];
    int qh=0,qt=0;
    for(int i=1;i<=N;i++) dep[i]=-1;
    dep[1]=0; par[0][1]=0; minw[0][1]=0;
    qq[qt++]=1; ocnt=0;
    while(qh<qt){
        int u=qq[qh++]; order[ocnt++]=u;
        for(int e=head[u]; e!=-1; e=nxt[e]){
            int v=to[e];
            if(dep[v]==-1){
                dep[v]=dep[u]+1;
                par[0][v]=u;
                minw[0][v]=wt[e];
                qq[qt++]=v;
            }
        }
    }
    for(int k=1;k<LOG;k++){
        for(int i=0;i<ocnt;i++){
            int v=order[i];
            int p=par[k-1][v];
            if(p){
                par[k][v]=par[k-1][p];
                minw[k][v]= minw[k-1][v] < minw[k-1][p] ? minw[k-1][v] : minw[k-1][p];
            } else {
                par[k][v]=0;
                minw[k][v]=0;
            }
        }
    }
    scanf("%d",&C);
    /* output buffer */
    static char out[5*50000*8];
    int opos=0;
    for(int c=0;c<C;c++){
        int x,y; scanf("%d %d",&x,&y);
        int ans=1000000000;
        if(dep[x]<dep[y]){ int t=x; x=y; y=t; }
        int d=dep[x]-dep[y];
        for(int k=0; d; k++, d>>=1){
            if(d&1){
                if(minw[k][x] && minw[k][x]<ans) ans=minw[k][x];
                x=par[k][x];
            }
        }
        if(x!=y){
            for(int k=LOG-1;k>=0;k--){
                if(par[k][x]!=par[k][y]){
                    if(minw[k][x] && minw[k][x]<ans) ans=minw[k][x];
                    if(minw[k][y] && minw[k][y]<ans) ans=minw[k][y];
                    x=par[k][x]; y=par[k][y];
                }
            }
            if(minw[0][x] && minw[0][x]<ans) ans=minw[0][x];
            if(minw[0][y] && minw[0][y]<ans) ans=minw[0][y];
        }
        opos += sprintf(out+opos,"%d\n",ans);
    }
    fwrite(out,1,opos,stdout);
    return 0;
}
